import { access, cp, mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const scriptDirectory = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(scriptDirectory, "..");
const variant = process.argv[2] ?? "";
if (variant && !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(variant)) throw new Error("Invalid physical-test build variant");
const outputName = `dist-physical-test${variant ? `-${variant}` : ""}`;
const output = path.join(root, outputName);
const marker = path.join(output, ".nova-prime-physical-test-build");
if (path.basename(output) !== outputName || !output.startsWith(`${root}${path.sep}`)) {
  throw new Error("Refusing to write outside the dedicated physical-test output directory");
}
try {
  await access(output);
  throw new Error("Physical-test output already exists; inspect and remove only the dedicated generated folder before rebuilding");
} catch (error) {
  if (error?.code !== "ENOENT") throw error;
}

await mkdir(output, { recursive: true });
await writeFile(marker, "Generated by scripts/build-physical-bundle.mjs. Do not store user data here.\n", "utf8");
await cp(path.join(root, "physical-test.html"), path.join(output, "index.html"));
await cp(path.join(root, "physical-test.css"), path.join(output, "physical-test.css"));
await cp(path.join(root, "LICENSE"), path.join(output, "LICENSE"));
await cp(path.join(root, "THIRD_PARTY_NOTICES.md"), path.join(output, "THIRD_PARTY_NOTICES.md"));

const files = [
  "src/app/physical-test-bootstrap.js",
  "src/application/robot/nova-robot-connection.js",
  "src/application/robot/robot-diagnostics.js",
  "src/application/robot/robot-executor.js",
  "src/application/robot/robot-safety-monitor.js",
  "src/domain/drills/schema.js",
  "src/domain/shared/id.js",
  "src/infrastructure/robot/md5.js",
  "src/infrastructure/robot/nova-protocol.js",
  "src/infrastructure/robot/web-bluetooth-transport.js",
];
for (const relative of files) {
  const target = path.resolve(output, relative);
  if (!target.startsWith(`${output}${path.sep}`)) throw new Error(`Unsafe output path: ${relative}`);
  await mkdir(path.dirname(target), { recursive: true });
  await cp(path.join(root, relative), target);
}

const packageJson = JSON.parse(await readFile(path.join(root, "package.json"), "utf8"));
await writeFile(path.join(output, "build-meta.json"), `${JSON.stringify({
  name: packageJson.name,
  version: packageJson.version,
  distribution: "physical-test-only",
  physicalTestOnly: true,
  buildVariant: variant || "standard",
  commandScope: "single-confirmed-conservative-ball",
}, null, 2)}\n`, "utf8");
console.log(`Built isolated Nova Prime physical-test app ${packageJson.version} in ${outputName}/`);
